#!/usr/bin/env python3
"""Flatten a directory tree one level at a time, keeping name collisions."""

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path


PROTECTED_AT_ROOT = {
    ".Spotlight-V100",
    ".TemporaryItems",
    ".Trashes",
    ".fseventsd",
}


def preview(root: Path) -> None:
    """Print the final result without relying on imaginary intermediate moves."""
    reserved = {entry.name.casefold() for entry in root.iterdir()}

    def available(name: str) -> Path:
        if name.casefold() not in reserved:
            reserved.add(name.casefold())
            return root / name
        if name.startswith(".") and name.count(".") == 1:
            stem, suffix = name, ""
        else:
            stem, suffix = os.path.splitext(name)
        number = 2
        while f"{stem} {number}{suffix}".casefold() in reserved:
            number += 1
        result = f"{stem} {number}{suffix}"
        reserved.add(result.casefold())
        return root / result

    def visit(directory: Path) -> None:
        with os.scandir(directory) as scan:
            entries = sorted(scan, key=lambda entry: entry.name.casefold())
        for entry in entries:
            source = Path(entry.path)
            if directory == root and entry.name in PROTECTED_AT_ROOT:
                print(f"PROTECT {source}")
            elif entry.is_dir(follow_symlinks=False):
                visit(source)
                print(f"RMDIR   {source}")
            elif directory != root:
                print(f"FINAL   {source} -> {available(entry.name)}")

    visit(root)


def keep_both_destination(parent: Path, name: str) -> Path:
    """Return an unused Finder-like `name 2.ext` destination."""
    candidate = parent / name
    if not os.path.lexists(candidate):
        return candidate

    if name.startswith(".") and name.count(".") == 1:
        stem, suffix = name, ""
    else:
        stem, suffix = os.path.splitext(name)

    number = 2
    while True:
        candidate = parent / f"{stem} {number}{suffix}"
        if not os.path.lexists(candidate):
            return candidate
        number += 1


def flatten_directory(directory: Path, root: Path, execute: bool) -> tuple[int, int]:
    moved = removed = 0

    # Descend through real directories first. Symlinks are cargo, never tunnels.
    with os.scandir(directory) as scan:
        entries = sorted(scan, key=lambda entry: entry.name.casefold())

    for entry in entries:
        source = Path(entry.path)
        if directory == root and entry.name in PROTECTED_AT_ROOT:
            print(f"PROTECT {source}")
            continue

        if entry.is_dir(follow_symlinks=False):
            child_moved, child_removed = flatten_directory(source, root, execute)
            moved += child_moved
            removed += child_removed

            # In preview mode the child still physically contains its files.
            print(f"RMDIR   {source}")
            if execute:
                source.rmdir()
                removed += 1

    # Rescan so cargo just lifted out of child directories is included. Files
    # already at the chosen root stay there rather than escaping to its parent.
    if directory != root:
        with os.scandir(directory) as scan:
            cargo = sorted(scan, key=lambda entry: entry.name.casefold())
        for entry in cargo:
            source = Path(entry.path)
            destination = keep_both_destination(directory.parent, entry.name)
            print(f"MOVE    {source} -> {destination}")
            if execute:
                source.rename(destination)
                moved += 1

    return moved, removed


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Move every nested file toward ROOT, then remove empty folders."
    )
    parser.add_argument("root", type=Path, help="tree to flatten (for example /Volumes/storage)")
    parser.add_argument(
        "--execute",
        action="store_true",
        help="perform changes; without this flag, only print a preview",
    )
    args = parser.parse_args()

    root = args.root.expanduser().resolve()
    if not root.is_dir():
        parser.error(f"not a directory: {root}")
    if root == Path("/"):
        parser.error("refusing to flatten the operating-system root directory")

    print(f"ROOT    {root}")
    print("MODE    " + ("EXECUTE" if args.execute else "PREVIEW (no changes)"))

    try:
        if not args.execute:
            preview(root)
            print("DONE    preview only; no files or directories were changed")
            return 0
        moved, removed = flatten_directory(root, root, True)
    except (OSError, PermissionError) as error:
        print(f"ERROR   {error}", file=sys.stderr)
        return 1

    print(f"DONE    moved {moved} entries; removed {removed} directories")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
